from pathlib import Path
import json,hashlib,zipfile,struct,shutil
ROOT=Path(__file__).resolve().parent;GEN=ROOT/'generated'
commit=zipfile.ZipFile(ROOT/'mpfb2-master.zip').comment.decode()
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assets=[]
used=['skins/young_asian_female','skins/young_asian_male','eyes/high-poly','eyes/materials','eyebrows/eyebrow001','eyelashes/eyelashes01','hair/long01','hair/short04','clothes/toigo_camisole_top','clothes/toigo_fisherman_sweater','clothes/toigo_wool_pants','clothes/toigo_halter_dress_knee_length','clothes/toigo_female_suit_2','clothes/toigo_male_suit_3','clothes/shoes02']
for directory in used:
 for p in sorted((ROOT/'system-assets'/directory).glob('*')):
  if p.is_file():assets.append({'path':p.relative_to(ROOT/'system-assets').as_posix(),'bytes':p.stat().st_size,'sha256':sha(p)})
models=[]
for sex in ['female','male']:
 p=GEN/f'{sex}.glb';b=p.read_bytes();size,jtype=struct.unpack_from('<II',b,12);g=json.loads(b[20:20+size]);m=json.loads((GEN/f'{sex}-manifest.json').read_text())
 assert b[:4]==b'glTF' and len(b)==struct.unpack_from('<I',b,8)[0]
 assert all('uri' not in x for x in g.get('buffers',[])+g.get('images',[]))
 assert len(g.get('skins',[]))>0
 layers=sorted({n.get('extras',{}).get('avatarLayer') for n in g['nodes'] if n.get('extras',{}).get('avatarLayer')})
 models.append({'file':p.name,'bytes':len(b),'sha256':sha(p),'layers':layers,'rigBones':len(m['bones']),'sourceVertices':sum(x['verts'] for x in m['meshes']),'meshCount':len(g.get('meshes',[])),'materialCount':len(g.get('materials',[])),'embeddedImages':[{'name':x.get('name'),'mimeType':x['mimeType']} for x in g.get('images',[])],'extensionsUsed':g.get('extensionsUsed',[])})
provenance={'version':1,'createdDate':'2026-10-18','generator':'Blender 5.1.2 + MPFB2 3af0cd5a2ffba072e93a34e5f6f494fdc4813ddf','description':'Custom assembled adult fashion avatars. No personal photographs, scans, identity reconstruction or remote inference. Built-in clothing layers are authored templates, not automatic reconstruction of uploaded wardrobe photos.','assetLicense':'CC0-1.0','sourceCodeLicenseNote':'MPFB2 is GPL-3.0 software used only at offline build time; its graphical assets and output are CC0 according to the upstream split license. MPFB is not bundled into the web runtime.','upstream':{'repository':f'https://github.com/makehumancommunity/mpfb2/tree/{commit}','archiveUrl':'https://codeload.github.com/makehumancommunity/mpfb2/zip/refs/heads/master','resolvedArchiveCommit':commit,'immutableArchiveUrl':f'https://codeload.github.com/makehumancommunity/mpfb2/zip/{commit}','archiveSha256':sha(ROOT/'mpfb2-master.zip'),'license':f'https://github.com/makehumancommunity/mpfb2/blob/{commit}/LICENSE.md','assetLicense':f'https://github.com/makehumancommunity/mpfb2/blob/{commit}/LICENSE.ASSETS.md','licenseConfirmation':'https://static.makehumancommunity.org/about/license.html','assetPacks':[f'https://static.makehumancommunity.org/assets/assetpacks/{x}.html' for x in ['makehuman_system_assets','shirts01','pants01','dress01','suits01']]},'credits':['MakeHuman / MPFB Community','Data Collection AB','Joel Palmius','Jonas Hauquier','Margaret Toigo (camisole, sweater, wool trousers, halter dress, suits)'],'modifications':['Custom adult female/male macro shape and subtle facial target combination','Game-engine rig and skinning','Fitted independent clothing parts with smooth radial ease','Removed redundant pants from suit mesh to create separate blazer layer','Removed high sock geometry; styled clean opaque low shoes','Dark brown hair PBR factor, explicit alpha and reduced specular','Female rear hair refitted against closed blazer while preserving front and scalp','Female authored covered-body faces retain geometry and normals with conditional avatarHiddenByOuterwear material visibility','Female original trousers preserved as Basis with conditional OuterwearLayerFit native morph beneath closed blazer','Opaque always-on torso/pelvis privacy cover','Subdivision and shape baking; all texture resources embedded','Web texture sizes bounded; JPEG quality 92 for opaque albedo, PNG for alpha','Authoring previews use relaxed upper arms; exported GLBs retain the binding pose and application runtime owns arm posture'],'models':models,'sourceAssetFiles':assets,'buildScriptSha256':sha(ROOT/'build-avatars.py')}
